function ScreenHomepage({
  onLaunchFeature1,
  onLaunchFeature2,
  onLaunchFeature3,
  onLaunchFeature4,
  onLaunchFeature5,
  onLaunchFeature6,
  onLaunchFeature7,
  onLaunchFeature8,
  onLaunchFeature9,
  onLaunchFeature10,
  onLaunchAbout,
  onLaunchOverview,
  setView,
  actorRole,
  setActorRole,
  currentUser
}) {
  const isDistrictAdmin = (currentUser && (currentUser.role === 'admin' || currentUser.role === 'officer' || currentUser.role === 'district_admin')) || actorRole === 'admin' || actorRole === 'officer';

  const [activeHeroSlide, setActiveHeroSlide] = useState(() => {
    if (typeof window !== 'undefined' && window.location.hash.includes('slide=')) {
      const match = window.location.hash.match(/slide=(\d+)/);
      if (match) return parseInt(match[1], 10) % 4;
    }
    return 0;
  });
  const [isHeroPaused, setIsHeroPaused] = useState(false);

  useEffect(() => {
    const handleHashChange = () => {
      if (window.location.hash.includes('slide=')) {
        const match = window.location.hash.match(/slide=(\d+)/);
        if (match) setActiveHeroSlide(parseInt(match[1], 10) % 4);
      }
    };
    window.addEventListener('hashchange', handleHashChange);
    return () => window.removeEventListener('hashchange', handleHashChange);
  }, []);

  useEffect(() => {
    if (isHeroPaused) return;
    const timer = setInterval(() => {
      setActiveHeroSlide((prev) => (prev + 1) % 4);
    }, 4000);
    return () => clearInterval(timer);
  }, [isHeroPaused]);

  const roleDescriptions = {
    worker: 'Frontline ASHA/ANM Mode: Assisted symptom triage, scheduled follow-up visits, pending referral monitoring, and medicine reservation.',
    patient: 'Self-Service Patient Mode: Autonomous triage, appointment booking, medicine & lab test search with radius fallback, and digital Health ID.',
    doctor: 'Clinical Specialist Mode: Prioritized patient queues, video/audio/chat consultations, digital EMR prescriptions, and closed-loop referrals.',
    shop_owner: 'Medical Shop Mode: Real-time inventory CRUD, stock level updates, and incoming customer reservation fulfillment.',
    lab_staff: 'Diagnostic Laboratory Mode: Diagnostic test catalog management, sample intake tracking, and dual clinical/patient report publishing.',
    facility: 'Facility Administrator Mode: Referral intake, arriving patient check-ins, bed/ICU resource status updates, and emergency alerts.',
    admin: 'District Health Administrator Mode: Pan-district epidemiological surveillance, shortage forecasts, inter-hospital logistics, and scheme governance.'
  };

  const modules = [
    {
      id: 'feature1',
      code: 'Module 01',
      icon: '',
      title: 'Smart Care Navigator',
      description: 'Answer a few questions and get routed to the right level of care: self-care, teleconsult, or in-person in seconds.',
      actionLabel: 'Launch Triage',
      action: onLaunchFeature1,
      badge: 'Autonomous Triage'
    },
    {
      id: 'feature2',
      code: 'Module 02',
      icon: '',
      title: 'Teleconsultation',
      description: 'Secure video visits with licensed clinicians, with notes and prescriptions synced straight to your record.',
      actionLabel: 'Start Teleconsult',
      action: onLaunchFeature2,
      badge: 'Prioritized Telehealth'
    },
    {
      id: 'feature3',
      code: 'Module 03',
      icon: '',
      title: 'Referral Routing',
      description: 'Automatically match patients to the right specialist and facility, with status tracked end to end.',
      actionLabel: 'Open Referrals',
      action: onLaunchFeature3,
      badge: 'Closed-Loop Care'
    },
    {
      id: 'feature4',
      code: 'Module 04',
      icon: '',
      title: 'Health Monitoring',
      description: 'Track vitals and trends from connected devices, with smart alerts when something needs attention.',
      actionLabel: 'Open Follow-Ups',
      action: onLaunchFeature4,
      badge: 'Dynamic Risk Engine'
    },
    {
      id: 'feature5',
      code: 'Module 05',
      icon: '',
      title: 'Unified Health Records',
      description: 'Every visit, lab, and prescription in one encrypted timeline you can share with any provider.',
      actionLabel: 'Open Records',
      action: onLaunchFeature5,
      badge: 'ABDM Interoperable'
    },
    {
      id: 'feature6',
      code: 'Module 06',
      icon: '',
      title: 'Medicine Search',
      description: 'Look up medicines, dosages, and interactions, then order refills without leaving the app.',
      actionLabel: 'Open Medicine & Lab',
      action: onLaunchFeature6,
      badge: 'Geo Logistics'
    },
    {
      id: 'feature7',
      code: 'Module 07',
      icon: '',
      title: isDistrictAdmin ? 'Facility Operations Dashboard' : 'Hospital Services & Performance',
      description: isDistrictAdmin ? 'Multi-source operations overview: Care Continuity Index, live prioritized queue, bed/ICU resource status meters, and alerts.' : 'Real-time hospital performance, care quality index, inpatient bed availability, and specialty department schedules.',
      actionLabel: isDistrictAdmin ? 'Open Dashboard' : 'View Hospital Services',
      action: onLaunchFeature7,
      badge: isDistrictAdmin ? 'Operations Control' : 'Hospital Quality'
    },
    {
      id: 'feature8',
      code: 'Module 08',
      icon: '',
      title: isDistrictAdmin ? 'Govt Health Schemes (Admin View)' : 'AI Govt Health Scheme Finder',
      description: isDistrictAdmin ? 'District scheme quota allocation, beneficiary verification audit, package catalog, and fund disbursal oversight.' : 'RAG scheme discovery with deterministic eligibility rules engine, single-document gap filling, and verified benefit matching.',
      actionLabel: isDistrictAdmin ? 'Access Schemes Admin' : 'Find Schemes',
      action: onLaunchFeature8,
      badge: isDistrictAdmin ? 'Admin Audit' : 'Affordable Care'
    },
    {
      id: 'feature9',
      code: 'Module 09',
      icon: '',
      title: 'District Admin Command Center',
      description: 'Pan-India multi-hospital live surveillance, shortage forecasting, epidemic early warning (CDC EARS/CUSUM), and inter-hospital transfer coordination.',
      actionLabel: 'Command Center',
      action: onLaunchFeature9,
      badge: 'Surveillance & Logistics'
    },
    {
      id: 'feature10',
      code: 'Module 10',
      icon: '',
      title: 'MediBot',
      description: 'Autonomous voice & action agent: book doctor appointments, find emergency beds, set medicine dosage reminders, and navigate MedVeda.',
      actionLabel: 'Launch AI Agent',
      action: onLaunchFeature10,
      badge: 'Bilingual & Actions'
    }
  ];

  const displayModules = isDistrictAdmin
    ? modules.filter(m => m.id === 'feature9' || m.id === 'feature8')
    : (actorRole === 'patient'
      ? modules.filter(m => m.id !== 'feature9')
      : modules);

  return (
    <div className="w-full">
      {/* 3D Clinical Video Showcase (Very Top of Homepage) */}
      <Home3DVideoShowcase
        onLaunchOverview={onLaunchOverview || (() => setView && setView('overview'))}
        onLaunchAbout={onLaunchAbout || (() => setView && setView('about'))}
      />

      {/* Welcome to MedVeda & Core Motives Section (Just after Video, Before Carousels) */}
      <HomeWelcomeMotiveSection
        onLaunchFeature1={onLaunchFeature1}
        onLaunchFeature2={onLaunchFeature2}
        onLaunchFeature8={onLaunchFeature8}
      />

      {/* 3D MEDIA CARD CAROUSEL FOR OUR FEATURES (using our already built cards) */}
      <HomeFeaturesCarousel3D modules={displayModules} />

      {/* Our Platform: All Feature Cards (3 Cards Per Row, Clean & Professional) */}
      <HomeOurPlatformSection
        isDHO={isDistrictAdmin}
        onLaunchFeature1={onLaunchFeature1}
        onLaunchFeature2={onLaunchFeature2}
        onLaunchFeature3={onLaunchFeature3}
        onLaunchFeature4={onLaunchFeature4}
        onLaunchFeature5={onLaunchFeature5}
        onLaunchFeature6={onLaunchFeature6}
        onLaunchFeature7={onLaunchFeature7}
        onLaunchFeature8={onLaunchFeature8}
        onLaunchFeature9={onLaunchFeature9}
        onLaunchFeature10={onLaunchFeature10}
      />

      {/* Healthcare Impact at a Glance Section (Full Width, matches carousel) */}
      <HealthcareImpactSection
        onLaunchFeature1={onLaunchFeature1}
        onLaunchFeature2={onLaunchFeature2}
        onLaunchFeature4={onLaunchFeature4}
        onLaunchFeature7={onLaunchFeature7}
      />

      {/* Verified User Testimonials Section */}
      <HomeTestimonialsSection />

      {/* Floating Cookie Consent Banner */}
      <HomeCookieBanner />
    </div>
  );
}

