function PatientAvatarPortrait({ sex = 'male', size = 'lg' }) {
  const dimClass = size === 'xl'
    ? 'w-24 h-24 sm:w-28 sm:h-28'
    : size === 'md'
    ? 'w-16 h-16 sm:w-20 sm:h-20'
    : 'w-20 h-20 sm:w-24 sm:h-24';
  const svgClass = size === 'xl'
    ? 'w-20 h-20 sm:w-24 sm:h-24'
    : size === 'md'
    ? 'w-14 h-14 sm:w-16 sm:h-16'
    : 'w-16 h-16 sm:w-20 sm:h-20';

  return (
    <div className={`${dimClass} rounded-2xl bg-slate-50 border border-slate-200/90 shadow-2xs shrink-0 overflow-hidden flex items-center justify-center`}>
      {sex === 'female' ? (
        <svg className={`${svgClass} text-[#1565C0]/85 mt-2`} viewBox="0 0 64 64" fill="none">
          <circle cx="32" cy="22" r="12" fill="#0284c7" fillOpacity="0.15" stroke="#0284c7" strokeWidth="2.2" />
          <path d="M20 22c0-7.5 5.4-13 12-13s12 5.5 12 13c0 3.5-1.2 6.8-3 9.2" stroke="#0369a1" strokeWidth="2.2" strokeLinecap="round" />
          <path d="M12 58c1.5-11 9.5-18 20-18s18.5 7 20 18" fill="#0284c7" fillOpacity="0.12" stroke="#0284c7" strokeWidth="2.2" strokeLinecap="round" />
        </svg>
      ) : (
        <svg className={`${svgClass} text-[#1565C0]/85 mt-2`} viewBox="0 0 64 64" fill="none">
          <circle cx="32" cy="22" r="12" fill="#1565C0" fillOpacity="0.15" stroke="#1565C0" strokeWidth="2.2" />
          <path d="M12 58c1.5-11 9.5-18 20-18s18.5 7 20 18" fill="#1565C0" fillOpacity="0.12" stroke="#1565C0" strokeWidth="2.2" strokeLinecap="round" />
        </svg>
      )}
    </div>
  );
}

