      address: hospitalProfile.address === 'Not added' ? '' : hospitalProfile.address,
      district: hospitalProfile.district === 'Not added' ? '' : hospitalProfile.district,
      state: hospitalProfile.state === 'Not added' ? '' : hospitalProfile.state,
      phone: hospitalProfile.phone === 'Not added' ? '' : hospitalProfile.phone,
      pmjayCode: hospitalProfile.pmjayCode === 'Not added' ? '' : hospitalProfile.pmjayCode,
      totalBeds: hospitalProfile.totalBeds ?? '',
      occupiedBeds: hospitalProfile.occupiedBeds ?? '',
      icuTotal: hospitalProfile.icuTotal ?? '',
      icuAvailable: hospitalProfile.icuAvailable ?? '',
      oxygenCapacity: hospitalProfile.oxygenCapacity === 'Not added' ? '' : hospitalProfile.oxygenCapacity,
      emergencyBays: hospitalProfile.emergencyBays === 'Not added' ? '' : hospitalProfile.emergencyBays
