  const subCenter = currentUser?.subCenter || (isPrototype ? 'Sub-Center Katkamsandi (Ayushman Arogya Mandir)' : 'Not added');

  const userSolvedCases = Array.isArray(customData.solvedCases) ? customData.solvedCases : [];
